import io
from rich.console import Console
from rich.file_proxy import FileProxy

class MockFile:
    def write(self, text):
        pass
    def flush(self):
        pass

class MockFileWithIsattyTrue:
    def write(self, text):
        pass
    def flush(self):
        pass
    def isatty(self):
        return True

class MockFileWithIsattyFalse:
    def write(self, text):
        pass
    def flush(self):
        pass
    def isatty(self):
        return False

class MockFileWithIsattyError:
    def write(self, text):
        pass
    def flush(self):
        pass
    def isatty(self):
        raise io.UnsupportedOperation()

def test_isatty():
    console = Console(force_terminal=True)

    # Case 1: No isatty method
    file1 = MockFile()
    proxy1 = FileProxy(console, file1)
    print(f"Case 1 (No isatty): {proxy1.isatty()} (expected False)")
    assert proxy1.isatty() is False

    # Case 2: isatty returns True
    file2 = MockFileWithIsattyTrue()
    proxy2 = FileProxy(console, file2)
    print(f"Case 2 (isatty True): {proxy2.isatty()} (expected True)")
    assert proxy2.isatty() is True

    # Case 3: isatty returns False
    file3 = MockFileWithIsattyFalse()
    proxy3 = FileProxy(console, file3)
    print(f"Case 3 (isatty False): {proxy3.isatty()} (expected False)")
    assert proxy3.isatty() is False

    # Case 4: isatty raises UnsupportedOperation
    file4 = MockFileWithIsattyError()
    proxy4 = FileProxy(console, file4)
    print(f"Case 4 (isatty Error): {proxy4.isatty()} (expected False)")
    assert proxy4.isatty() is False

if __name__ == "__main__":
    test_isatty()
